@startuml

class Animal {
  + ID : int
  + Name : string
}

class Breed {
  + Name : string
}

class Condition {
  + CommonName : string
  + ScientificName : string
}

class Appointment {
  + Date : date
  + Time : time
}

class Person {
  + ID : int
  + Name : string
  + Address : string
  + Phone : string
}

class Owner extends Person {}

class Physician extends Person {}

Animal "*" -- "0..1" Owner : belongs to
Animal "*" -- "0..1" Breed : has breed
Appointment "*" -- "1" Physician : responsible physician
Appointment "*" -- "1" Animal : attended by
Appointment "*" -- "1" Owner : attended by
Condition "*" -- "*" Breed : common in
Condition "*" -- "*" Appointment : detected in

@enduml

